import pytest
import unittest.mock
from unittest.mock import MagicMock
from bionetgen.simulator.csimulator import CSimWrapper, CSimulator
from bionetgen.core.exc import BNGSimulatorError


def test_set_parameters_error():
    with unittest.mock.patch("bionetgen.simulator.csimulator.ctypes.CDLL"):
        wrapper = CSimWrapper("dummy_lib_path", num_params=3, num_spec_init=2)
        with pytest.raises(BNGSimulatorError) as excinfo:
            wrapper.set_parameters([1.0, 2.0])
        # The exception message generated by BNGSimulatorError based on actual file contents
        assert "Expected 3 parameters, but got 2" in str(excinfo.value)


def test_csimulator_simulate():
    mock_model = MagicMock()

    spec_A = MagicMock()
    spec_A.count = 10.0
    spec_B = MagicMock()
    spec_B.count = "p_init_B"
    mock_model.species = {"A": spec_A, "B": spec_B}

    p_init_B = MagicMock()
    p_init_B.value = 20.0
    p_init_B.expr = "not_a_float"

    p1 = MagicMock()
    p1.expr = 1.0
    p2 = MagicMock()
    p2.expr = "2.0"

    mock_model.parameters = {
        "p_init_B": p_init_B,
        "p1": p1,
        "p2": p2,
        "_p3": MagicMock(),
    }

    csim = CSimulator.__new__(CSimulator)
    csim.model = mock_model

    mock_simulator = MagicMock()
    mock_simulator.simulate.return_value = ([0, 1, 2], [0, 0, 0], [1, 1, 1])
    csim._simulator = mock_simulator

    timepoints, obs_all, spcs_all = csim.simulate(t_start=0, t_end=10, n_steps=10)

    mock_simulator.set_species_init.assert_called_once_with([10.0, 20.0])
    mock_simulator.set_parameters.assert_called_once_with([1.0, 2.0])
    mock_simulator.simulate.assert_called_once_with(0, 10, 10)

    assert timepoints == [0, 1, 2]
    assert obs_all == [0, 0, 0]
    assert spcs_all == [1, 1, 1]
